'use client';
import {useEffect,useState} from 'react';
import {supabase} from '@/lib/supabase';
import AppShell from '@/components/AppShell';
const habits=[['calories','≤ 1,750 kcal'],['protein','≥ 120g protein'],['workout','Workout'],['steps','8,000 steps'],['water','2L water'],['creatine','Creatine'],['sleep','7h sleep'],['fasting','IF 16:8']] as const;
export default function Home(){
 const [weight,setWeight]=useState('77'); const [waist,setWaist]=useState(''); const [done,setDone]=useState<Record<string,boolean>>({}); const [msg,setMsg]=useState('');
 const current=Number(weight)||77, lost=Math.max(0,77-current), pct=Math.min(100,Math.max(0,(lost/12)*100));
 useEffect(()=>{(async()=>{if(!supabase)return; const {data}=await supabase.from('daily_logs').select('*').order('date',{ascending:false}).limit(1).maybeSingle(); if(data){setWeight(String(data.weight??77));setWaist(String(data.waist??''));setDone(data.habits??{})}})()},[]);
 const toggle=(k:string)=>setDone(x=>({...x,[k]:!x[k]}));
 async function save(){if(!supabase){setMsg('Demo mode — hubungkan .env.local ke Supabase untuk menyimpan data.');return} const today=new Date().toISOString().slice(0,10); const {error}=await supabase.from('daily_logs').upsert({date:today,weight:Number(weight),waist:waist?Number(waist):null,habits:done},{onConflict:'date'}); setMsg(error?error.message:'Check-in tersimpan ✓')}
 return <AppShell>
  <div className="top"><div><div className="eyebrow">15 Sep 2026 — 1 Jan 2027</div><h1 style={{margin:'5px 0'}}>CutTrack</h1></div><div className="avatar">IF</div></div>
  <section className="hero"><div className="eyebrow">Current weight</div><div className="weight">{current.toFixed(1)}<small style={{fontSize:18,marginLeft:8}}>kg</small></div><div className="progress"><div style={{width:`${pct}%`}}/></div><div className="stats"><div className="stat"><span className="muted">Start</span><b>77</b></div><div className="stat"><span className="muted">Lost</span><b>{lost.toFixed(1)}</b></div><div className="stat"><span className="muted">Goal</span><b>65</b></div></div></section>
  <section className="section"><h2>Quick check-in</h2><div className="inputrow"><input className="input" value={weight} onChange={e=>setWeight(e.target.value)} inputMode="decimal" placeholder="Weight kg"/><input className="input" value={waist} onChange={e=>setWaist(e.target.value)} inputMode="decimal" placeholder="Waist cm"/></div><button className="btn save" onClick={save}>Save today</button>{msg&&<div className="notice">{msg}</div>}</section>
  <section className="section"><h2>Today's habits</h2><div className="habits">{habits.map(([k,label])=><button key={k} className={`habit ${done[k]?'done':''}`} onClick={()=>toggle(k)}><b>{done[k]?'✓ ':''}{label}</b><span>{done[k]?'Completed':'Tap to complete'}</span></button>)}</div></section>
  <section className="section"><h2>Today's workout</h2><div className="card workout"><div><div className="eyebrow">Tuesday</div><b>Walk / Recovery</b><div className="muted" style={{marginTop:5}}>8,000+ steps</div></div><button className="btn" onClick={()=>toggle('workout')}>{done.workout?'Done ✓':'Complete'}</button></div></section>
 </AppShell>
}
